import {
  afterAll,
  beforeAll,
  beforeEach,
  describe,
  expect,
  it,
  vi,
} from "vitest";
import {
  boundary,
  usageFixture,
  usageOwner,
  setGating,
} from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import { createCampaign } from "@/lib/campaigns";
import { deliverOne, sendEmail } from "@/lib/inngest";
import { claimUsage, withUsageTransaction } from "@/lib/usage-ledger";
import { pauseOwner, pauseGmailProject } from "@/lib/sending-pause";
import { resolveUsagePeriods } from "@/lib/usage-periods";
import { reconcileUsageOwner } from "@/lib/usage-reconciliation";

function latch() {
  let release!: () => void;
  const promise = new Promise<void>((resolve) => {
    release = resolve;
  });
  return { promise, release };
}
describe.runIf(databaseTestsEnabled)("worker quota settlement", () => {
  let fixture: Awaited<ReturnType<typeof usageFixture>>;
  beforeAll(async () => {
    fixture = await usageFixture();
  });
  beforeEach(async () => {
    boundary.send.mockReset().mockResolvedValue({ data: { id: "accepted" } });
    await setGating(boundary.db, true);
  });
  afterAll(async () => {
    if (fixture) await fixture.close();
  });
  async function queued() {
    const f = await usageOwner(boundary.db);
    const campaign = await createCampaign(f.user.id, await f.input());
    const send = await boundary.db.send.findFirstOrThrow({
      where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
    });
    return { ...f, send };
  }
  it.each([false, true])(
    "worker failure closes only unclaimed work (claimed=%s)",
    async (claimed) => {
      const f = await queued();
      if (claimed)
        await withUsageTransaction(boundary.db, f.user.id, (owner) =>
          claimUsage(
            owner,
            f.send.id,
            resolveUsagePeriods(f.user, new Date()),
            true,
          ),
        );
      const onFailure = sendEmail.opts.onFailure;
      if (!onFailure) throw new Error("Email worker failure handler missing.");
      const args = {
        event: {
          data: { event: { data: { userId: f.user.id, sendId: f.send.id } } },
        },
      } as Parameters<typeof onFailure>[0];
      await onFailure(args);
      expect(
        await boundary.db.send.findFirst({
          where: { id: f.send.id, campaign: { userId: f.user.id } },
        }),
      ).toMatchObject(
        claimed
          ? { deliveryState: "ATTEMPTING" }
          : { status: "FAILED", deliveryState: "DONE" },
      );
      expect(
        await boundary.db.usageReservation.findFirst({
          where: { userId: f.user.id },
        }),
      ).toMatchObject({ status: claimed ? "ATTEMPTING" : "RELEASED" });
      if (!claimed) {
        await deliverOne(f.user.id, f.send.id);
        expect(boundary.send).not.toHaveBeenCalled();
      }
    },
  );
  it("calls Gmail once across duplicate events before, during and after submission, without a network-held owner lock", async () => {
    const f = await queued(),
      entered = latch(),
      finish = latch();
    boundary.send.mockImplementationOnce(async () => {
      entered.release();
      await finish.promise;
      return { data: { id: "one-call" } };
    });
    const first = deliverOne(f.user.id, f.send.id);
    await entered.promise;
    expect(await deliverOne(f.user.id, f.send.id)).toEqual({ outcome: "done" });
    await withUsageTransaction(boundary.db, f.user.id, async ({ tx }) => {
      await tx.user.update({
        where: { id: f.user.id },
        data: { lastActiveAt: new Date() },
      });
    });
    finish.release();
    expect(await first).toEqual({ outcome: "done" });
    await deliverOne(f.user.id, f.send.id);
    expect(boundary.send).toHaveBeenCalledOnce();
    expect(
      await boundary.db.usageReservation.findFirst({
        where: { userId: f.user.id },
      }),
    ).toMatchObject({ status: "CONFIRMED" });
  });
  it("admits simultaneous pre-claim duplicates only once", async () => {
    const f = await queued();
    await Promise.all(
      Array.from({ length: 12 }, () => deliverOne(f.user.id, f.send.id)),
    );
    expect(boundary.send).toHaveBeenCalledOnce();
  });
  it("retains uncertainty when Gmail accepts but the confirmation transaction fails", async () => {
    const f = await queued();
    await boundary.db.$executeRawUnsafe(
      `CREATE FUNCTION fixture_confirmation_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status='CONFIRMED' THEN RAISE EXCEPTION 'fixture rejected confirmation'; END IF; RETURN NEW; END $$`,
    );
    await boundary.db.$executeRawUnsafe(
      `CREATE TRIGGER fixture_confirmation_failure BEFORE UPDATE ON "UsageReservation" FOR EACH ROW EXECUTE FUNCTION fixture_confirmation_failure()`,
    );
    boundary.send.mockResolvedValueOnce({
      data: { id: "accepted-lost-confirmation" },
    });
    try {
      expect((await deliverOne(f.user.id, f.send.id)).outcome).toBe(
        "uncertain",
      );
    } finally {
      await boundary.db.$executeRawUnsafe(
        `DROP TRIGGER fixture_confirmation_failure ON "UsageReservation"`,
      );
      await boundary.db.$executeRawUnsafe(
        `DROP FUNCTION fixture_confirmation_failure()`,
      );
    }
    expect(
      await boundary.db.usageReservation.findFirst({
        where: { userId: f.user.id },
      }),
    ).toMatchObject({ status: "UNCERTAIN" });
    await deliverOne(f.user.id, f.send.id);
    expect(boundary.send).toHaveBeenCalledOnce();
    await reconcileUsageOwner(f.user.id);
    expect(
      await boundary.db.usageReservation.findFirst({
        where: { userId: f.user.id },
      }),
    ).toMatchObject({ status: "CONFIRMED" });
    expect(boundary.send).toHaveBeenCalledOnce();
  });
  it("retains a killed claim without submission and never retries it after lease expiry", async () => {
    const f = await queued();
    const at = new Date(Date.now());
    await withUsageTransaction(boundary.db, f.user.id, (owner) =>
      claimUsage(owner, f.send.id, resolveUsagePeriods(f.user, at), true, at),
    );
    await reconcileUsageOwner(f.user.id, new Date(+at + 120001));
    expect((await deliverOne(f.user.id, f.send.id)).outcome).toBe("uncertain");
    expect(boundary.send).not.toHaveBeenCalled();
    expect(
      await boundary.db.usageReservation.findFirst({
        where: { userId: f.user.id },
      }),
    ).toMatchObject({ status: "UNCERTAIN" });
  });
  it("repairs durable acceptance after a worker dies before settlement without resubmitting", async () => {
    const f = await queued(),
      at = new Date(Date.now());
    await withUsageTransaction(boundary.db, f.user.id, (owner) =>
      claimUsage(owner, f.send.id, resolveUsagePeriods(f.user, at), true, at),
    );
    await boundary.db.send.updateMany({
      where: { id: f.send.id, campaign: { userId: f.user.id } },
      data: { gmailMessageId: "accepted-before-crash", sentAt: at },
    });
    await reconcileUsageOwner(f.user.id, new Date(+at + 120001));
    await deliverOne(f.user.id, f.send.id);
    expect(boundary.send).not.toHaveBeenCalled();
    expect(
      await boundary.db.usageReservation.findFirst({
        where: { userId: f.user.id },
      }),
    ).toMatchObject({ status: "CONFIRMED" });
  });
  it.each([0, 500, 503])(
    "retains ambiguous submission (%i) and never resends",
    async (status) => {
      const f = await queued();
      boundary.send.mockRejectedValueOnce(
        status ? { response: { status } } : new Error("timeout"),
      );
      expect((await deliverOne(f.user.id, f.send.id)).outcome).toBe(
        "uncertain",
      );
      await deliverOne(f.user.id, f.send.id);
      expect(boundary.send).toHaveBeenCalledOnce();
      expect(
        await boundary.db.usageReservation.findFirst({
          where: { userId: f.user.id },
        }),
      ).toMatchObject({ status: "UNCERTAIN" });
    },
  );
  it.each([429, 403])(
    "finishes a definite %i throttle once and releases capacity",
    async (status) => {
      const f = await queued();
      boundary.send.mockRejectedValue({
        response: {
          status,
          data: { error: { errors: [{ reason: "userRateLimitExceeded" }] } },
        },
      });
      expect((await deliverOne(f.user.id, f.send.id)).outcome).toBe("done");
      expect(
        await boundary.db.send.findFirst({
          where: { id: f.send.id, campaign: { userId: f.user.id } },
        }),
      ).toMatchObject({
        status: "FAILED",
        deliveryState: "DONE",
        throttleRetries: 0,
      });
      expect(
        await boundary.db.usageReservation.findFirst({
          where: { userId: f.user.id },
        }),
      ).toMatchObject({ status: "RELEASED" });
      await deliverOne(f.user.id, f.send.id);
      expect(boundary.send).toHaveBeenCalledOnce();
    },
  );
  it.each([
    "throttleRetries",
    "credentialRetries",
    "preparationRetries",
  ] as const)(
    "retires a legacy queued %s without preparing or sending again",
    async (field) => {
      const f = await queued();
      await boundary.db.send.updateMany({
        where: { id: f.send.id, campaign: { userId: f.user.id } },
        data: { [field]: 1 },
      });
      expect((await deliverOne(f.user.id, f.send.id)).outcome).toBe("done");
      expect(
        await boundary.db.send.findFirst({
          where: { id: f.send.id, campaign: { userId: f.user.id } },
        }),
      ).toMatchObject({ status: "FAILED", deliveryState: "DONE" });
      expect(
        await boundary.db.usageReservation.findFirst({
          where: { userId: f.user.id },
        }),
      ).toMatchObject({ status: "RELEASED" });
      expect(boundary.gmail).not.toHaveBeenCalled();
      expect(boundary.send).not.toHaveBeenCalled();
    },
  );
  it("rebinds queued work at month rollover, defers when the destination is full, and retains its old reservation", async () => {
    const before = Date.parse("2026-10-31T23:59:50Z"),
      after = Date.parse("2026-11-01T00:00:01Z");
    const clock = vi.spyOn(Date, "now").mockReturnValue(before);
    try {
      const success = await queued();
      clock.mockReturnValue(after);
      expect((await deliverOne(success.user.id, success.send.id)).outcome).toBe(
        "done",
      );
      const current = await boundary.db.usageReservation.findFirstOrThrow({
        where: { userId: success.user.id },
      });
      expect(current.chargedAt).toEqual(new Date(after));
      const day = await boundary.db.usagePeriod.findFirstOrThrow({
        where: { userId: success.user.id, id: current.dailyPeriodId },
      });
      expect(day.startsAt).toEqual(new Date("2026-11-01"));
      clock.mockReturnValue(before);
      const blocked = await queued();
      const original = await boundary.db.usageReservation.findFirstOrThrow({
        where: { userId: blocked.user.id },
      });
      clock.mockReturnValue(after);
      await withUsageTransaction(
        boundary.db,
        blocked.user.id,
        async (owner) => {
          const { importUsageEvidence } = await import("@/lib/usage-ledger");
          for (let i = 0; i < 3; i++)
            await importUsageEvidence(owner, {
              sourceKey: `destination:${i}`,
              deliveryKey: null,
              chargedAt: new Date(after),
              timestampSource: "sentAt",
            });
        },
      );
      expect((await deliverOne(blocked.user.id, blocked.send.id)).outcome).toBe(
        "deferred",
      );
      expect(
        await boundary.db.usageReservation.findFirst({
          where: { userId: blocked.user.id },
        }),
      ).toMatchObject({
        dailyPeriodId: original.dailyPeriodId,
        monthlyPeriodId: original.monthlyPeriodId,
        status: "RESERVED",
        chargedAt: null,
      });
      expect(boundary.send).toHaveBeenCalledOnce();
    } finally {
      clock.mockRestore();
    }
  });
  it("keeps a request crossing midnight in its claim period without rolling usage into the next month", async () => {
    const before = Date.parse("2026-10-31T23:59:59Z"),
      after = Date.parse("2026-11-01T00:00:01Z");
    const clock = vi.spyOn(Date, "now").mockReturnValue(before);
    try {
      const f = await queued();
      boundary.send.mockImplementationOnce(async () => {
        clock.mockReturnValue(after);
        return { data: { id: "crossing" } };
      });
      expect((await deliverOne(f.user.id, f.send.id)).outcome).toBe("done");
      const row = await boundary.db.usageReservation.findFirstOrThrow({
        where: { userId: f.user.id },
      });
      expect(row.chargedAt).toEqual(new Date(before));
      const { readQuotaSnapshot } = await import("@/lib/quota-usage");
      expect(await readQuotaSnapshot(f.user.id)).toMatchObject({
        mode: "gated",
        daily: { sent: 0, reserved: 0 },
        monthly: { sent: 0, reserved: 0 },
      });
    } finally {
      clock.mockRestore();
    }
  });
  it("allows exact final-slot equality and cancels an oversized campaign after activation", async () => {
    const f = await usageOwner(boundary.db);
    const campaign = await createCampaign(f.user.id, await f.input(3));
    const sends = await boundary.db.send.findMany({
      where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
    });
    expect((await deliverOne(f.user.id, sends[0].id)).outcome).toBe("done");
    expect(boundary.send).toHaveBeenCalledOnce();
    const blocked = await usageOwner(boundary.db);
    await setGating(boundary.db, false);
    const extra = await createCampaign(blocked.user.id, await blocked.input(4));
    await setGating(boundary.db, true);
    const pending = await boundary.db.send.findFirstOrThrow({
      where: { campaignId: extra.id, campaign: { userId: blocked.user.id } },
    });
    expect((await deliverOne(blocked.user.id, pending.id)).outcome).toBe(
      "done",
    );
    expect(
      await boundary.db.send.count({
        where: {
          campaignId: extra.id,
          campaign: { userId: blocked.user.id },
          status: "CANCELLED",
        },
      }),
    ).toBe(4);
    expect(
      await boundary.db.usageReservation.count({
        where: { userId: blocked.user.id, status: "RELEASED" },
      }),
    ).toBe(4);
    expect(boundary.send).toHaveBeenCalledOnce();
  });
  it("reloads a committed kill switch after Gmail preparation and never claims", async () => {
    const f = await queued();
    boundary.gmail.mockImplementationOnce(async () => {
      await boundary.db.systemControl.update({
        where: { key: "global" },
        data: { sendingEnabled: false },
      });
      return {
        email: f.user.email,
        gmail: { users: { messages: { send: boundary.send } } },
      };
    });
    try {
      expect((await deliverOne(f.user.id, f.send.id)).outcome).toBe("deferred");
      expect(boundary.send).not.toHaveBeenCalled();
      expect(
        await boundary.db.usageReservation.findFirst({
          where: { userId: f.user.id },
        }),
      ).toMatchObject({ status: "RESERVED" });
    } finally {
      await boundary.db.systemControl.update({
        where: { key: "global" },
        data: { sendingEnabled: true },
      });
    }
  });
  it("reloads suspension and sending controls after network preparation", async () => {
    const f = await queued();
    boundary.gmail.mockImplementationOnce(async () => {
      await boundary.db.user.update({
        where: { id: f.user.id },
        data: {
          isSuspended: true,
          suspendedAt: new Date(),
          suspensionReason: "Fixture",
        },
      });
      return {
        email: f.user.email,
        gmail: { users: { messages: { send: boundary.send } } },
      };
    });
    expect((await deliverOne(f.user.id, f.send.id)).outcome).toBe("deferred");
    expect(boundary.send).not.toHaveBeenCalled();
    expect(
      await boundary.db.usageReservation.findFirst({
        where: { userId: f.user.id },
      }),
    ).toMatchObject({ status: "RESERVED" });
  });
  it("requires reconnect immediately after a definite 401 without another send", async () => {
    const f = await queued();
    boundary.send.mockRejectedValue({ response: { status: 401 } });
    expect((await deliverOne(f.user.id, f.send.id)).outcome).toBe("done");
    expect(
      await boundary.db.user.findUnique({ where: { id: f.user.id } }),
    ).toMatchObject({
      gmailAuthorized: false,
      gmailPauseReason: "RECONNECT_REQUIRED",
    });
    expect(
      await boundary.db.usageReservation.findFirst({
        where: { userId: f.user.id },
      }),
    ).toMatchObject({ status: "RELEASED" });
    await deliverOne(f.user.id, f.send.id);
    expect(boundary.send).toHaveBeenCalledOnce();
  });
  it.each(["invalid_grant", "domainPolicy"])(
    "cancels remaining READY work for %s, retaining attempted reservations",
    async (reason) => {
      const f = await usageOwner(boundary.db),
        campaign = await createCampaign(f.user.id, await f.input(3));
      const sends = await boundary.db.send.findMany({
        where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
        orderBy: { id: "asc" },
      });
      await withUsageTransaction(boundary.db, f.user.id, (owner) =>
        claimUsage(
          owner,
          sends[2].id,
          resolveUsagePeriods(f.user, new Date()),
          true,
        ),
      );
      const provider =
        reason === "invalid_grant"
          ? { response: { data: { error: "invalid_grant" } } }
          : {
              response: {
                status: 403,
                data: { error: { errors: [{ reason }] } },
              },
            };
      boundary.gmail.mockRejectedValueOnce(provider);
      expect((await deliverOne(f.user.id, sends[0].id)).outcome).toBe("done");
      const rows = await boundary.db.usageReservation.findMany({
        where: { userId: f.user.id },
      });
      expect(rows.filter((r) => r.status === "RELEASED")).toHaveLength(2);
      expect(rows.filter((r) => r.status === "ATTEMPTING")).toHaveLength(1);
      expect(boundary.send).not.toHaveBeenCalled();
    },
  );
  it("finishes preparation failure without another attempt", async () => {
    const f = await queued();
    boundary.gmail.mockRejectedValueOnce({ response: { status: 503 } });
    expect((await deliverOne(f.user.id, f.send.id)).outcome).toBe("done");
    await deliverOne(f.user.id, f.send.id);
    expect(boundary.gmail).toHaveBeenCalledOnce();
    expect(
      await boundary.db.send.findUnique({ where: { id: f.send.id } }),
    ).toMatchObject({ preparationRetries: 0, status: "FAILED" });
    expect(
      await boundary.db.usageReservation.findFirst({
        where: { userId: f.user.id },
      }),
    ).toMatchObject({ status: "RELEASED" });
    expect(boundary.send).not.toHaveBeenCalled();
  });
  it.each(["owner", "global"])(
    "fences a final claim when a %s pause arrives during preparation",
    async (kind) => {
      const f = await queued(),
        entered = latch(),
        finish = latch();
      const prepared = {
        email: f.user.email,
        name: "Fixture",
        gmail: { users: { messages: { send: boundary.send } } },
      };
      boundary.gmail.mockImplementationOnce(async () => {
        entered.release();
        await finish.promise;
        return prepared;
      });
      const work = deliverOne(f.user.id, f.send.id);
      await entered.promise;
      if (kind === "owner")
        await pauseOwner(
          f.user.id,
          "PROVIDER_DAILY_LIMIT",
          new Date(Date.now() + 3600000),
        );
      else await pauseGmailProject(new Date(Date.now() + 3600000));
      finish.release();
      expect((await work).outcome).toBe("deferred");
      expect(boundary.send).not.toHaveBeenCalled();
      expect(
        await boundary.db.usageReservation.findFirst({
          where: { userId: f.user.id },
        }),
      ).toMatchObject({ status: "RESERVED" });
      await boundary.db.systemControl.update({
        where: { key: "global" },
        data: { gmailProjectPauseUntil: null },
      });
    },
  );
  it("honors a daily provider deadline and releases the failed email reservation", async () => {
    const f = await queued(),
      deadline = new Date(Date.now() + 7200000);
    boundary.send.mockRejectedValueOnce({
      response: {
        status: 429,
        headers: { "retry-after": deadline.toUTCString() },
        data: { error: { message: "User-rate limit exceeded (Mail sending)" } },
      },
    });
    expect((await deliverOne(f.user.id, f.send.id)).outcome).toBe("done");
    const user = await boundary.db.user.findUniqueOrThrow({
      where: { id: f.user.id },
    });
    expect(user.gmailPauseReason).toBe("PROVIDER_DAILY_LIMIT");
    expect(+user.gmailPauseUntil!).toBe(Date.parse(deadline.toUTCString()));
    expect(
      await boundary.db.usageReservation.findFirst({
        where: { userId: f.user.id },
      }),
    ).toMatchObject({ status: "RELEASED" });
  });
});
